package dev.chieppa.squash.schemagen.reference

import dev.chieppa.squash.character.build.AxisCurveParams
import dev.chieppa.squash.character.build.MAX_SPIRAL_TURNS
import dev.chieppa.squash.character.build.GenericParams
import dev.chieppa.squash.character.build.MAX_CURVE_PLACES
import dev.chieppa.squash.character.build.MIN_CURVE_PLACES
import dev.chieppa.squash.character.build.HandJoints
import dev.chieppa.squash.character.build.HandLandmarks
import dev.chieppa.squash.character.build.HandSockets
import dev.chieppa.squash.character.model.CopySpec
import dev.chieppa.squash.character.build.JoinParams
import dev.chieppa.squash.character.build.PlacementParams
import dev.chieppa.squash.character.build.RestDirection
import dev.chieppa.squash.character.build.RigParams
import dev.chieppa.squash.character.build.ViewParams
import dev.chieppa.squash.character.model.SIZE_PARAM
import dev.chieppa.squash.document.Side
import dev.chieppa.squash.document.View

/** The dotted part parameters: what each holds, and the recipe field that writes it where there is one. */
internal object PartParameters {
    private const val N = 1
    private const val SOCKET = "<socket>"
    private const val JOINT = "<joint>"

    fun render(): String = buildString {
        appendLine("# Part parameters")
        appendLine()
        appendLine(
            "Every part holds its shape as numbers by name: its template's parameters (templates.md) and the dotted ones below. A recipe part's " +
                "named fields write the dotted ones; anything without a field goes in `params` by its key. A key a named field writes cannot also be in " +
                "`params`. Flags are 1 or 0. `<n>` is the number the recipe entry gives. Generated by `generateSchemas`.",
        )
        appendLine()
        append(table(listOf("key", "holds", "recipe field"), rows()))
        appendLine()
        appendLine("`generic.section` counts: " + GenericParams.PROFILES.mapIndexed { i, p -> "$i ${p.name.lowercase()}" }.joinToString(", ") + ".")
        appendLine("`move.rest` counts: " + RestDirection.entries.joinToString(", ") { "${it.ordinal} ${restWord(it)}" } + ".")
        appendLine("`joint.<n>.hinge` counts: " + HandJoints.HINGES.mapIndexed { i, h -> "$i ${h.name.lowercase()}" }.joinToString(", ") + ".")
        appendLine("A row socket `socket.<n>` with `count` k is the sockets `socket.<n>.0` to `socket.<n>.<k-1>`, which parts name in `socket`; a part on `socket.<n>.<i>` starts at the size the row gives that place.")
        appendLine("A hand-made joint's bone owns its part from its u to the next joint; a part with hand-made joints gains a `${HandJoints.TIP}` joint at its end, limits ${nums(HandJoints.TIP_LIMITS.min, HandJoints.TIP_LIMITS.max)}, when its template has none there.")
    }

    private fun key(text: String) = code(text.replace(".$N", ".<n>"))

    private fun rows(): List<List<String>> = listOf(
        listOf(code(SIZE_PARAM), "scales the part's length and width", "`size`"),
        listOf(key(PlacementParams.LEAN), "degrees the part leans toward its own up, ${num(PlacementParams.MAX_ANGLE)} at most either way", "`lean`"),
        listOf(key(PlacementParams.OUTWARD), "degrees it leans out from the body's middle plane, mirrored on the right; ${num(PlacementParams.MAX_ANGLE)} at most either way", "`outward`"),
        listOf(key(PlacementParams.REST), "the direction it rests in, in place of its template's", "`rest`"),
        listOf(key(PlacementParams.ROLL), "degrees it rolls about its own axis, its up turning toward its v 0.25 side, after rest, lean and outward; any angle", "`roll`"),
        listOf(key(PlacementParams.TOE_OUT), "degrees it turns about its own up, its tip swinging away from the body's middle plane, mirrored on the right, after rest, lean, outward and roll: a foot's toe-out; any angle", "`toeOut`"),
        listOf(key(ViewParams.TOP_MIDDLE), "flag: Top's midline moves the part's middle sideways along its length, as Side's moves it up; unset, Top sets width alone", "`topMiddle`"),
        listOf(code(PlacementParams.joint(JOINT)), "u a template joint is moved to", "`jointsAt`"),
        listOf(code(PlacementParams.socketU(SOCKET)) + ", " + code(PlacementParams.socketV(SOCKET)), "where a socket this part offers is moved to, both sides", "`socketsAt`"),
        listOf(code(PlacementParams.socketSink(SOCKET)), "how deep a part on a socket this part offers sits, times that part's own sink, 0 or more; the socket's own when unset", "`socketsAt` third number"),
        listOf(code(PlacementParams.socketU(SOCKET, Side.LEFT)) + ", `.right.u`, `.left.v`, `.right.v`", "the same for one side alone", "`params`"),
        listOf(key(HandSockets.u(N)) + ", " + key(HandSockets.v(N)), "a hand-made socket's place", "`sockets[].u`, `.v`"),
        listOf(key(HandSockets.outward(N)), "degrees its outward direction turns from the surface's normal toward the part's end, ${num(HandSockets.MAX_OUTWARD)} at most", "`sockets[].outward`"),
        listOf(key(HandSockets.sink(N)), "how deep a part on it sits, times that part's own sink, 0 or more; 0 on the surface, 1 when unset", "`sockets[].sink`"),
        listOf(key(HandSockets.outset(N)), "how far a part on it stands off the surface along its normal before it sinks, in body units; 0 when unset. A part a garment owns stands on the cloth with an outset past the garment's fit and sink 0", "`sockets[].outset`"),
        listOf(key(HandSockets.pair(N)), "flag: a mirrored twin across the body's middle", "`sockets[].mirrored`"),
        listOf(key(HandSockets.count(N)), "a row of this many sockets, up to ${HandSockets.MAX_COUNT}", "`sockets[].count`"),
        listOf(key(HandSockets.to(N)), "the row's last socket's u", "`sockets[].to`"),
        listOf(key(HandSockets.toV(N)), "the row's last socket's v; a whole turn from its v closes the row round the part, its sockets a turn's share apart", "`sockets[].toV`"),
        listOf(key(HandSockets.size(N)), "the size a part on the row's first socket starts at; with spread or repeat, each copy's size, times the part's own", "`sockets[].size`"),
        listOf(key(HandSockets.falloff(N)), "the size on the row's last socket, a share of the first's; with spread, the share copies fall to at the area's edges", "`sockets[].falloff`"),
        listOf(key(HandSockets.spread(N)), "one socket showing this many copies of the part on it over the area from u to to and v to toV, up to ${CopySpec.MAX_COPIES}", "`sockets[].spread.count`"),
        listOf(key(HandSockets.seed(N)) + ", " + key(HandSockets.spacing(N)) + ", " + key(HandSockets.edge(N)), "the seed a spread's places and jitter are picked by; the least distance between its copies, in body units; the outer share of its area its size falls off over", "`sockets[].spread`"),
        listOf(key(HandSockets.sizeJitter(N)) + ", " + key(HandSockets.leanJitter(N)) + ", " + key(HandSockets.turnJitter(N)), "how far each copy's size varies either way, as a share; the most degrees it leans from the normal; the most it turns about itself", "`sockets[].spread`"),
        listOf(key(HandSockets.droop(N)), "degrees each copy tilts from the normal toward the body's down along the surface, its up turned to the normal: hair lying over a head", "`sockets[].spread.droop`"),
        listOf(key(HandSockets.repeat(N)), "one socket showing this many copies of the part on it along the path from (u, v) through its via places to (to, toV); 0 as many as its pitch fits", "`sockets[].path.count`"),
        listOf(key(HandSockets.viaU(N, 0)) + ", " + key(HandSockets.viaV(N, 0)), "a place a path runs through, from 0 on, ${HandSockets.MAX_VIA} at most", "`sockets[].path.via`"),
        listOf(key(HandSockets.pitch(N)) + ", " + key(HandSockets.roll(N)) + ", " + key(HandSockets.sag(N)), "the step between a path's copies, in body units, from the part's size when unset; the degrees each rolls more than the one before; how far the path droops at its middle, in body units", "`sockets[].path`"),
        listOf(key(HandJoints.u(N)), "a hand-made joint's u, at least ${num(HandJoints.GAP)} from the ends and from other joints", "`joints[].u`"),
        listOf(key(HandJoints.hinge(N)), "its hinge, counted below", "`joints[].hinge`"),
        listOf(key(HandJoints.low(N)) + ", " + key(HandJoints.high(N)), "its limits in degrees, ${num(HandJoints.DEFAULT_LIMITS.min)} and ${num(HandJoints.DEFAULT_LIMITS.max)} when unset, ${num(HandJoints.MAX_LIMIT)} at most", "`joints[].low`, `.high`"),
        listOf(key(HandJoints.stretch(N)), "flag: a stretch handle may move it", "`joints[].stretch`"),
        listOf(key(HandLandmarks.u(N)) + ", " + key(HandLandmarks.v(N)), "a hand-made landmark's place", "`landmarks[]`"),
        listOf(key(GenericParams.SECTION), "a generic part's section, counted below", "`generic.section`"),
        listOf(View.entries.joinToString(", ") { key(GenericParams.view(it)) }, "flags: which views shape a generic part", "`generic.views`"),
        listOf(key(GenericParams.RINGS) + ", " + key(GenericParams.SEGMENTS), "a generic part's rings along and control points round", "`generic.rings`, `.segments`"),
        listOf(key(AxisCurveParams.along(N)) + ", " + key(AxisCurveParams.up(N)) + ", " + key(AxisCurveParams.side(N)), "a place the part's axis curves through, from 1 on, in the part's own axes as fractions of its length: along its rest, toward Side's +y, toward v 0.25; ${MIN_CURVE_PLACES} to ${MAX_CURVE_PLACES} replace its template's curve, on a template that sweeps (templates.md, curve column)", "`curve`"),
        listOf(key(AxisCurveParams.SPIRAL_TURNS) + ", " + key(AxisCurveParams.SPIRAL_PITCH) + ", " + key(AxisCurveParams.SPIRAL_SHRINK), "a spiral the axis coils in, in place of curve places: turns toward Side's +y (negative toward its underside, up to ${MAX_SPIRAL_TURNS.toInt()} either way), the coil's move toward v 0.25 a turn as a share of its first diameter, and its radius at the tip as a share of its first", "`spiral`"),
        listOf(key(JoinParams.INK), "0 leaves the join with its parent unlined; 1 or unset inks it", "`inkJoin`"),
        listOf(code(RigParams.reach(JOINT)), "how far the skin blend at a joint reaches, times the rig's guess, ${num(RigParams.MIN_REACH)} to ${num(RigParams.MAX_REACH)}", "`params`"),
    )
}
